```js
let refreshing = false;

async function request(url) {
  const res = await wx.p.request({ url });
  if (res.statusCode === 401) {
    if (!refreshing) {
      refreshing = true;
      await wx.p.login();
      refreshing = false;
    }
    return request(url);
  }
  return res;
}

Promise.all([request('/a'), request('/b')]);

假设 /a 与 /b 首次同时返回 401，wx.p.login() 完成前登录态不会恢复。
